from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Loop through the input string to identify and extract individual groups of nested parentheses
    groups = []
    current_group = ""
    for char in paren_string:
        if char == "(":
            current_group += char
        elif char == ")":
            current_group += char
            groups.append(current_group)
            current_group = ""

    # Step 3: Check if each extracted group is balanced
    def is_balanced(group):
        stack = []
        for char in group:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    balanced_groups = [group for group in groups if is_balanced(group)]

    # Step 4: Return the extracted groups as a list
    return balanced_groups

